import re

def extract_floats(text):
    pattern = r'-?\d+\.\d+|-?\d+'
    matches = re.findall(pattern, text)
    result = []
    for match in matches:
        try:
            value = float(match)
            result.append(value)
        except ValueError:
            continue
    return result

