def remove_vowels(text: str) -> str:
    if not isinstance(text, str):
        raise TypeError("Input must be a string")
    if len(text) == 0:
        return ""
    vowels = frozenset("aeiouAEIOU")
    return "".join(c for c in text if c not in vowels)

