def capitalize_first(text):
    if not text:
        return ""
    if len(text) == 1:
        return text.upper()
    first = text[0].upper()
    rest = text[1:]
    if first != text[0]:
        return first + rest
    if rest == "":
        return text
    return text[0] + rest.upper() if first == text[0].lower() else first + rest[1:] if len(rest) > 1 else first + rest

