    result = split_csv_string(sample_csv)
    print(result)

TOKEN_MAP = {'sep': ',', 'strip': str.strip}

def split_and_strip(source):
    raw_parts = source.split(TOKEN_MAP['sep'])
    return [TOKEN_MAP['strip'](part) for part in raw_parts]

