        return ''
    n = len(sentence)
    if n == 0:
        return ''

    def word_generator(text):
        start = None
        for i, char in enumerate(text):
            if char != ' ':
                if start is None:
                    start = i
            elif start is not None:
                yield text[start:i]
                start = None
        if start is not None:
            yield text[start:]
    words = list(word_generator(sentence))
    words.reverse()
    return ' '.join(words)
