def reverse_words(sentence):
    if not isinstance(sentence, str):
        raise TypeError("Input must be a string")
    n = len(sentence)
    result_words = []
    start = 0
    i = 0
    while i < n:
        if sentence[i] == ' ':
            if start < i:
                word = sentence[start:i]
                result_words.insert(0, word)
            start = i + 1
        i += 1
    if start < n:
        word = sentence[start:n]
        result_words.insert(0, word)
    return ' '.join(result_words)

