        if not s:
            return s

        result = []
        i = len(s) - 1
        while i >= 0:
            while i >= 0 and s[i] == ' ':
                i -= 1
            if i < 0:
                break
            j = i
            while i >= 0 and s[i] != ' ':
                i -= 1
            word = s[i + 1:j + 1]
            if result:
                result.append(' ')
            result.append(word)

        return ''.join(result)

