def find_duplicate_characters(text):
    char_count = {}
    for char in text:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1
    duplicates = [char for char, count in char_count.items() if count > 1]
    duplicates.sort()
    return duplicates

