    test_input = "banana"
    result = find_repeated_characters(test_input)
    print(result)

def find_repeated_characters(s):
    seen = set()
    repeated = set()
    for char in s:
        if char in seen:
            repeated.add(char)
        else:
            seen.add(char)

    result = []
    for char in s:
        if char in repeated:
            result.append(char)
            repeated.remove(char)

    return ''.join(result)

