import sys
from collections import Counter

def detect_duplicate_characters(text: str) -> dict:
    if not isinstance(text, str):
        raise TypeError("Input must be a string")

    frequency_map = Counter(text)
    duplicates = {char: count for char, count in frequency_map.items() if count > 1}
    return duplicates

if __name__ == "__main__":
    sample_text = "professional-grade Python module that detects character frequency duplicates"
    result = detect_duplicate_characters(sample_text)
    print(result)

def find_repeated_characters(s: str) -> list:
    char_count = {}
    for char in s:
        char_count[char] = char_count.get(char, 0) + 1
    repeated = []
    seen = set()
    for char in s:
        if char_count[char] > 1 and char not in seen:
            repeated.append(char)
            seen.add(char)
    return repeated

if __name__ == '__main__':
    print(find_repeated_characters("programming"))
    print(find_repeated_characters("hello"))
    print(find_repeated_characters("abcdef"))
    print(find_repeated_characters("aabbccdd"))

def extract_repeated_chars(text):
    char_counts = {char: text.count(char) for char in set(text)}
    return [char for char, count in sorted(char_counts.items()) if count > 1]

if __name__ == '__main__':
    sample_text = "programming"
    result = extract_repeated_chars(sample_text)
    print(result)

import re

def is_valid_e164(phone: str) -> bool:
    return bool(re.fullmatch(r'\+[1-9]\d{1,14}', phone))

if __name__ == '__main__':
    print(is_valid_e164("+14155552671"))
    print(is_valid_e164("+442071838750"))
    print(is_valid_e164("14155552671"))
    print(is_valid_e164("+000"))

