def is_valid_phone_number(phone):
    if not phone:
        return False
    if not phone.startswith('+'):
        return False

    rest = phone[1:]
    if not rest:
        return False

    if not rest[0].isdigit():
        return False

    plus_digits_count = 0
    temp = rest
    while temp and temp[0].isdigit():
        plus_digits_count += 1
        temp = temp[1:]

    if plus_digits_count < 1 or plus_digits_count > 3:
        return False

    if not temp:
        return False

    main_digits_count = 0
    while temp and temp[0].isdigit():
        main_digits_count += 1
        temp = temp[1:]

    if main_digits_count < 7 or main_digits_count > 10:
        return False

    if temp:
        return False

    return True

