    print(validate_phone_number("+919876543210"))
    print(validate_phone_number("15551234567"))
    print(validate_phone_number("+1555"))
    print(validate_phone_number("+1234567"))

def validate_phone_number(phone_number: str) -> bool:
    if not phone_number:
