    country_code = 0
    rest_idx = 0
    length = len(rest)
    while rest_idx < length and rest[rest_idx] == '0':
        rest_idx += 1
    if rest_idx > 3:
        return False
    num_digits = length - rest_idx
    if num_digits < 7 or num_digits > 10:
        return False
    return True

