import re

def process_string(input_string: str) -> str:
    if input_string is None:
        raise ValueError('Input string cannot be None')
    stripped = input_string.strip()
    if not stripped:
        raise ValueError('Input string is empty after stripping')
    chars_to_keep = set()
    for c in stripped:
        if c.isdigit() or c == '-' or c == '+':
            chars_to_keep.add(c)
    table = {}
    for i in range(65536):
        c = chr(i)
        if c in stripped and c not in ['-', '+'] and (not c.isdigit()):
            table[i] = None
        elif c in ['-', '+'] and c not in stripped:
            table[i] = None
        elif c.isdigit() and c not in stripped:
            table[i] = None
        else:
            table[i] = i
    keep_chars = set('0123456789-+')
    trans_table = {}
    for i in range(65536):
        c = chr(i)
        if c in keep_chars:
            trans_table[i] = i
        else:
            trans_table[i] = None
    cleaned = stripped.translate(trans_table)
    if not re.match('^[+-]?\\d+$', cleaned):
        raise ValueError(f"Cleaned string '{cleaned}' does not consist solely of integers")
    if not cleaned:
        raise ValueError('Cleaned string is empty')
    int_value = int(cleaned)
    return str(int_value)
if __name__ == '__main__':
    test_string = '  -1,234.56  '
    result = process_string(test_string)
    print(result)

def clean_and_verify_integer_string(s):
    chars_to_remove = "".join(chr(c) for c in range(128) if not chr(c).isdigit() and chr(c) not in "-+")
    translation_table = str.maketrans("", "", chars_to_remove)
    cleaned = s.translate(translation_table)
    cleaned = cleaned.strip("-+")
    if not cleaned:
        return False
    try:
        int(cleaned)
        return True
    except ValueError:
        return False

if __name__ == '__main__':
    test_strings = ["123abc456", "-789", "+101", "12.34", "42"]
    for s in test_strings:
        result = clean_and_verify_integer_string(s)
        print(result)

