    translation_table = str.maketrans('', '', ' \t\n\r\v\f,.:;!?@#$%^&*()[]{}|\\\'\"`~+-_=<>')
    cleaned = text.translate(translation_table)
    if cleaned == '':
        return False
    return cleaned.isdigit()

