        "+123456789012345",
        "+01",
        "1",
        "+",
        "+abc",
        "+9999999999999999",
        123
    ]
    results = []
    for sample in samples:
        try:
            outcome = validator.validate(sample)
            results.append(f"Valid: {sample} -> {outcome}")
        except Exception as exc:
            results.append(f"Invalid: {sample} -> {exc}")
    for result_line in results:
        print(result_line)

