def snake_to_camel(s: str) -> str:
    if not s:
        return ""

    parts = s.split('_')

    if parts[0] == '':
        if s.startswith('_'):
            parts[0] = '_'
        else:
            parts[0] = ''

    if len(parts) == 1:
        return parts[0]

    result_parts = [parts[0]]

    for part in parts[1:]:
        if part == '':
            continue
        result_parts.append(part.capitalize())

    return ''.join(result_parts)

