def snake_to_camel(text):
    if not text:
        return text
    parts = text.split('_')
    if not parts:
        return text
    first = parts[0]
    if not first:
        return '_'.join(p.capitalize() for p in parts if p)
    return first + ''.join(p.capitalize() for p in parts[1:])

