def to_camel_case(text):
    if not text:
        return text
    parts = text.split('_')
    if not parts or not parts[0]:
        return text
    result = []
    result.append(parts[0])
    for part in parts[1:]:
        if not part:
            continue
        first_char = part[0]
        rest = part[1:]
        result.append(first_char.upper() + rest)
    return ''.join(result)

