def snake_to_camel(snake_case: str) -> str:
    parts = snake_case.split('_')
    if len(parts) == 0:
        return ''
    if len(parts) == 1 and not parts[0].isidentifier() and parts[0] == '':
        return ''
    return parts[0] + ''.join(word.capitalize() for word in parts[1:])

