import itertools

def compress_repeated_chars(sequence):
    for char, group in itertools.groupby(sequence):
        count = sum((1 for _ in group))
        yield (char, count)

def reconstruct_sequence(encoded):
    return ''.join((char * count for char, count in encoded))
