def compress_floats(data, tolerance=1e-9):
    if not data:
        return []

    compressed = []
    current_value = data[0]
    count = 1

    for i in range(1, len(data)):
        if abs(data[i] - current_value) <= tolerance:
            count += 1
        else:
            compressed.append((current_value, count))
            current_value = data[i]
            count = 1

    compressed.append((current_value, count))
    return compressed

