def run_length_decode(encoded: str) -> str:
    if not encoded:
        return ""

    result = []
    i = 0
    while i < len(encoded):
        char = encoded[i]
        i += 1
        count_str = ""
        while i < len(encoded) and encoded[i].isdigit():
            count_str += encoded[i]
            i += 1
        count = int(count_str) if count_str else 1
        result.append(char * count)

    return "".join(result)

