    result.append(str(count) + current_char)
    return "".join(result)

def rle_decode(text):
    if not text:
        return ""
    result = []
    num_str = []
    for char in text:
        if char.isdigit():
            num_str.append(char)
        else:
            count = int("".join(num_str))
            result.append(char * count)
            num_str = []
    return "".join(result)

