def run_length_encode(data):
    if not data:
        return ""

    encoded = []
    current_char = data[0]
    count = 1

    for char in data[1:]:
        if char == current_char:
            count += 1
        else:
            encoded.append(str(count) + current_char)
            current_char = char
            count = 1

    encoded.append(str(count) + current_char)
    return "".join(encoded)

