        return []
    result = []
    current_char = data[0]
    count = 1
    for char in data[1:]:
        if char == current_char:
            count += 1
        else:
            result.append((current_char, count))
            current_char = char
            count = 1
    result.append((current_char, count))
    return result

def run_length_encode_iterable(data_iter):
    result = []
    try:
        current_char = next(data_iter)
    except StopIteration:
        return result
    count = 1
    for char in data_iter:
        if char == current_char:
            count += 1
        else:
            result.append((current_char, count))
            current_char = char
            count = 1
    result.append((current_char, count))
    return result

def run_length_encode_iterator_based(data):
    if not data:
        return []
    group_iter = itertools.groupby(data)
    result = []
    for char, group in group_iter:
        count = sum(1 for _ in group)
        result.append((char, count))
    return result

if __name__ == '__main__':
    sample_string = "WWWWWWWWWWWWBWWWWWWWWWWWWWWBWWWWWWWWWWWWWW"
    encoded_result = run_length_encode_iterator_based(sample_string)
    print(encoded_result)

def run_length_encode(s):
    if not s:
        return ""

    result = []
    iterator = iter(s)
    prev_char = next(iterator)
    count = 1

    for char in iterator:
        if char == prev_char:
            count += 1
        else:
            result.append(f"{count}{prev_char}")
            prev_char = char
            count = 1

    result.append(f"{count}{prev_char}")

    return "".join(result)

if __name__ == '__main__':
    sample_string = "aaabbc"
    encoded = run_length_encode(sample_string)
    print(encoded)

def run_length_encode(data):
    if not data:
        return ""
    iterator = iter(data)
    try:
        current_char = next(iterator)
    except StopIteration:
        return ""
    count = 1
    result = []
    for char in iterator:
        if char == current_char:
            count += 1
        else:
            result.append(f"{current_char}{count}")
            current_char = char
            count = 1
    result.append(f"{current_char}{count}")
    return "".join(result)

if __name__ == '__main__':
    sample_input = "AAABBBCCCCDDDEEFFFF"
    encoded_output = run_length_encode(sample_input)
    print(encoded_output)

import itertools

def rle_encode(input_string):
    if not input_string:
        return ""

    encoded_parts = []

    for char, group in itertools.groupby(input_string):
        length = sum(1 for _ in group)
        if length > 3:
            encoded_parts.append(f"{length}{char}")
        else:
            encoded_parts.append(char * length)

    return "".join(encoded_parts)

if __name__ == '__main__':
    sample_input = "aabcccccaaa"
    result = rle_encode(sample_input)
    print(result)
